import time
import functools
from typing import Any, Callable, Dict, List, Optional, Tuple, Union

_registry: Dict[str, Union["Counter", "Gauge", "Histogram"]] = {}


class Counter:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: int = 0

